LEDGER = [
    ("queue held 15k msg/s for 60 min", "observed", "load test 2024-11 run 47", None),
    ("BF peak will be ~12k msg/s", "inferred", None, "marketing adds flash sale"),
    ("consumer lag recovers in <5 min", "observed", "staging chaos drill graph", None),
    ("DLQ handler covers all poison messages", "observed", None, None),
    ("payments retries are idempotent", "observed", "replay test 0 dupes in 10k", None),
    ("oncall can absorb the new alert load", "inferred", None, None),
]


def score_ledger(rows):
    laundered = []
    naked = []
    effective = 0
    for i, (claim, tag, source, invalidation) in enumerate(rows, 1):
        if tag == "observed" and source is None:
            laundered.append(i)
        elif tag == "observed":
            effective += 1
        if tag == "inferred" and invalidation is None:
            naked.append(i)
    pct = round(100 * effective / len(rows))
    ready = not laundered and not naked and pct >= 60
    return {"laundered": laundered, "naked": naked, "pct": pct, "ready": ready}


if __name__ == "__main__":
    r = score_ledger(LEDGER)
    for i in r["laundered"]:
        print(f"row {i} LAUNDERED: '{LEDGER[i - 1][0][:34]}' claims observed, no source")
    for i in r["naked"]:
        print(f"row {i} NAKED: '{LEDGER[i - 1][0][:34]}' inferred, no invalidation")
    eff = sum(1 for c, t, s, _ in LEDGER if t == "observed" and s)
    print(f"observed (with source): {eff}/{len(LEDGER)} ({r['pct']}%)")
    print(f"laundered: {len(r['laundered'])}  naked inferences: {len(r['naked'])}")
    if r["ready"]:
        print("verdict: REVIEW-READY")
    elif r["laundered"]:
        print(f"verdict: NOT REVIEW-READY - retag {len(r['laundered'])} laundered row(s)")
    elif r["naked"]:
        print(f"verdict: NOT REVIEW-READY - add invalidation to {len(r['naked'])} row(s)")
    else:
        print(f"verdict: NOT REVIEW-READY - observed ratio {r['pct']}% < 60%")

