MEMO = [
    ("situation", "two consumers today, five planned by Q3; direct call couples deploys"),
    ("decision", "publish order events to the shared bus; consumers own projections"),
    ("constraint", "ownership boundary: Orders deployable without coordinating consumers"),
    ("rejected", "versioned sync API also considered but the team preferred the bus"),
    ("verify", "we will monitor the bus closely after cutover"),
    ("invalidate", "if projected consumers stay at 2 or fewer by Q3, revisit the bus tax"),
]


def lint_memo(memo):
    pos = {}
    body = {}
    for i, (name, text) in enumerate(memo, 1):
        pos[name] = i
        body[name] = text
    r1 = pos.get("constraint", 0) > 0 and pos.get("decision", 0) > 0 and pos["constraint"] < pos["decision"]
    r2 = False
    if "rejected" in body and "constraint" in body:
        c_words = {w.lower().strip(";:,.") for w in body["constraint"].split() if len(w) > 5}
        r_words = {w.lower().strip(";:,.") for w in body["rejected"].split() if len(w) > 5}
        r2 = len(c_words & r_words) > 0
    r3 = "verify" in body and any(ch.isdigit() for ch in body["verify"])
    r4 = "invalidate" in body
    return {"R1": r1, "R2": r2, "R3": r3, "R4": r4}, pos


if __name__ == "__main__":
    results, pos = lint_memo(MEMO)
    labels = {
        "R1": f"constraint before decision (constraint@{pos.get('constraint', 0)} decision@{pos.get('decision', 0)})",
        "R2": "rejected option engages the constraint",
        "R3": "verification carries a threshold",
        "R4": "invalidation condition present",
    }
    for rid in ("R1", "R2", "R3", "R4"):
        print(f"{rid} {'PASS' if results[rid] else 'FAIL'} {labels[rid]}")
    score = sum(1 for v in results.values() if v)
    print(f"score: {score}/4")
    if score == 4:
        print("memo status: SHIPPABLE")
    else:
        print(f"memo status: BOUNCE - fix {4 - score} rule(s)")

tradeoff-framing.code:
CRITERIA = [
    ("time to ship", 4),
    ("blast-radius isolation", 3),
    ("ops burden", 2),
    ("team familiarity", 1),
]

SCORES = {
    "time to ship":            {"extend-monolith": 5, "worker-service": 2},
    "blast-radius isolation":  {"extend-monolith": 2, "worker-service": 5},
    "ops burden":              {"extend-monolith": 4, "worker-service": 2},
    "team familiarity":        {"extend-monolith": 5, "worker-service": 3},
}

OPTIONS = ["extend-monolith", "worker-service"]


def total_with(weights):
    return {
        o: sum(w * SCORES[c][o] for (c, _), w in zip(CRITERIA, weights))
        for o in OPTIONS
    }


def decide_and_probe():
    base_weights = [w for _, w in CRITERIA]
    totals = total_with(base_weights)
    t1, t2 = totals["extend-monolith"], totals["worker-service"]
    leader = "extend-monolith" if t1 > t2 else "worker-service"
    loser = "worker-service" if leader == "extend-monolith" else "extend-monolith"
    probes = []
    for idx, (crit, w) in enumerate(CRITERIA):
        found = None
        for wprime in range(0, 21):
            if wprime == w:
                continue
            trial = list(base_weights)
            trial[idx] = wprime
            t = total_with(trial)
            if t[loser] > t[leader]:
                if found is None or abs(wprime - w) < abs(found - w):
                    found = wprime
        probes.append((crit, w, found))
    return totals, probes


if __name__ == "__main__":
    totals, probes = decide_and_probe()
    t1, t2 = totals["extend-monolith"], totals["worker-service"]
    print(f"totals: extend-monolith={t1} worker-service={t2}")
    leader = "extend-monolith" if t1 > t2 else "worker-service"
    print(f"leader: {leader} by {abs(t1 - t2)}")
    best = None
    for crit, w, wprime in probes:
        if wprime is None:
            print(f"flip via {crit}: cannot flip in [0,20]")
        else:
            d = abs(wprime - w)
            print(f"flip via {crit}: weight {w} -> {wprime} (distance {d})")
            if best is None or d < best[1]:
                best = (crit, d)
    print(f"forcing variable: {best[0]}")

dependency-management.code:
TASKS = {
    "auth-api-v2":        (3, []),
    "token-migration":    (2, ["auth-api-v2"]),
    "fraud-callback-port":(2, []),
    "rehearsal":          (1, ["fraud-callback-port"]),
    "settlement-export":  (1, []),
    "reconciliation-test":(1, ["settlement-export"]),
    "cutover":            (0, ["token-migration", "rehearsal", "reconciliation-test"]),
}


def analyze(tasks, goal):
    ef = {}

    def earliest(t):
        if t in ef:
            return ef[t]
        dur, deps = tasks[t]
        ef[t] = dur + max((earliest(d) for d in deps), default=0)
        return ef[t]

    length = earliest(goal)
    for t in tasks:
        earliest(t)

    dependents = {t: [] for t in tasks}
    for t, (_, deps) in tasks.items():
        for d in deps:
            dependents[d].append(t)

    lf = {}

    def latest(t):
        if t in lf:
            return lf[t]
        if not dependents[t]:
            lf[t] = length
        else:
            lf[t] = min(latest(u) - tasks[u][0] for u in dependents[t])
        return lf[t]

    slack = {t: latest(t) - ef[t] for t in tasks}

    path = []
    frontier = [t for t in sorted(tasks) if not tasks[t][1] and slack[t] == 0]
    node = frontier[0]
    while node != goal:
        path.append(node)
        node = next(u for u in sorted(dependents[node]) if slack[u] == 0)
    path.append(goal)
    return {"length": length, "path": path, "slack": slack}


if __name__ == "__main__":
    r = analyze(TASKS, "cutover")
    print(f"project length: {r['length']} weeks")
    print(f"critical path: {' -> '.join(r['path'])}")
    for name in sorted(t for t in TASKS if t != "cutover"):
        print(f"slack {name}: {r['slack'][name]}w")
    daily = [t for t in sorted(TASKS) if t != "cutover" and r["slack"][t] == 0]
    biweekly = [t for t in sorted(TASKS) if t != "cutover" and r["slack"][t] >= 2]
    print(f"attention: daily={', '.join(daily)}")
    print(f"attention: biweekly={', '.join(biweekly)}")

