LAYERS = {
    "decision proof":    ["constraint", "selected", "killed_option", "kill_reason"],
    "operational proof": ["failure_mode", "watch_signal", "threshold"],
    "transfer proof":    ["stricter_variant", "what_changes"],
}

PROMPTS = {
    "decision proof": "what constraint survives even if the deadline moves?",
    "operational proof": "what would you watch to see this failing a week early?",
    "transfer proof": "same decision, but 10x the volume - what breaks first?",
}

PACKET = {
    "constraint": "no new on-call load this half (SRE freeze)",
    "selected": "SQS FIFO per-tenant queues",
    "killed_option": "self-managed Kafka",
    "kill_reason": "we would operate the cluster; violates the freeze",
    "failure_mode": "FIFO throughput cap stalls exports past 3k msg/s",
    "watch_signal": None,
    "threshold": None,
    "stricter_variant": None,
    "what_changes": None,
}


def analyze_packet(packet):
    missing = {}
    complete = 0
    for layer, fields in LAYERS.items():
        gone = [f for f in fields if packet.get(f) is None]
        missing[layer] = gone
        if not gone:
            complete += 1
    weakest = max(LAYERS, key=lambda l: (len(missing[l]), -list(LAYERS).index(l)))
    return {"missing": missing, "complete": complete, "weakest": weakest}


if __name__ == "__main__":
    r = analyze_packet(PACKET)
    for layer, fields in LAYERS.items():
        missing = r["missing"][layer]
        present = len(fields) - len(missing)
        line = f"{layer}: {present}/{len(fields)}"
        if missing:
            line += f" [MISSING: {', '.join(missing)}]"
        print(line)
    print(f"layers complete: {r['complete']}/3")
    print(f"weakest layer: {r['weakest']}")
    print(f"coaching prompt: {PROMPTS[r['weakest']]}")
    if r["complete"] == 3:
        print("packet: DEFENSIBLE")
    else:
        print(f"packet: NOT YET - mentee cannot survive {r['weakest']} questions")

conflict-repair.code:
INVARIANTS = {
    "payments": ["refund p99 <= 150ms"],
    "platform": ["no sync coupling to payments DB"],
}

PREFERRED = {"payments": "direct-calls", "platform": "shared-queue"}

PASSES = {
    "shared-queue": {
        "refund p99 <= 150ms": False,
        "no sync coupling to payments DB": True,
    },
    "direct-calls": {
        "refund p99 <= 150ms": True,
        "no sync coupling to payments DB": False,
    },
    "hybrid: queue + direct refund-ack endpoint": {
        "refund p99 <= 150ms": True,
        "no sync coupling to payments DB": True,
    },
}


def repair(invariants, passes, preferred):
    other = {"payments": "platform", "platform": "payments"}
    violations = {}
    for team, option in preferred.items():
        failed = [inv for inv in invariants[other[team]] if not passes[option][inv]]
        violations[team] = failed
    real = all(violations[t] for t in preferred)
    every = [inv for team_invs in invariants.values() for inv in team_invs]
    viable = [o for o in passes if all(passes[o][inv] for inv in every)]
    return {"violations": violations, "real": real, "viable": viable}


if __name__ == "__main__":
    r = repair(INVARIANTS, PASSES, PREFERRED)
    n_pay = len(INVARIANTS["payments"])
    n_plat = len(INVARIANTS["platform"])
    print(f"invariants: {n_pay + n_plat} (payments: {n_pay}, platform: {n_plat})")
    for team in ("payments", "platform"):
        v = r["violations"][team]
        print(f"{team} option '{PREFERRED[team]}' violates: {', '.join(v)}")
    print(f"conflict is real: {'yes' if r['real'] else 'no'}")
    print(f"viable: {', '.join(r['viable']) if r['viable'] else 'none'}")
    if r["viable"]:
        print(f"signable: {r['viable'][0]}")
    else:
        print("signable: ESCALATE - no option passes both")

